def tonelli_shanks(a, p):
    # Tonelli-Shanks algorithm for modular square root when p ≡ 1 (mod 4)
    assert pow(a, (p - 1) // 2, p) == 1, "a is not a quadratic residue mod p"

    # Find Q and S such that p-1 = Q * 2^S with Q odd
    Q = p - 1
    S = 0
    while Q % 2 == 0:
        Q //= 2
        S += 1

    # Find a non-residue z
    z = 2
    while pow(z, (p - 1) // 2, p) != p - 1:
        z += 1

    # Initialize variables
    M = S
    c = pow(z, Q, p)
    t = pow(a, Q, p)
    R = pow(a, (Q + 1) // 2, p)

    while t != 0 and t != 1:
        # Find the smallest i (0 < i < M) such that t^(2^i) ≡ 1 (mod p)
        t2i = t
        i = 0
        for i in range(1, M):
            t2i = pow(t2i, 2, p)
            if t2i == 1:
                break

        # Update variables
        b = pow(c, 2 ** (M - i - 1), p)
        M = i
        c = pow(b, 2, p)
        t = (t * c) % p
        R = (R * b) % p

    return R

def modular_sqrt(a, p):
    if p % 4 == 3:
        return pow(a, (p + 1) // 4, p)
    elif p % 4 == 1:
        return tonelli_shanks(a, p)
    else:
        raise ValueError("Unsupported modulus")

